// 양쪽 호스트가 같은 패키지/상태/사건을 실행해 결과 JSON을 대조한다.
export default function registerMod(netstorm) {
    // 공개 이름과 사본 조회·정규화 명령을 하나의 시작 사건에서 점검한다.
    netstorm.on('sessionStart', () => {
        netstorm.log('info', JSON.stringify({ names: Object.keys(netstorm), commands: Object.keys(netstorm.commands), state: netstorm.getState(), players: netstorm.getPlayers(), selection: netstorm.getSelection() }));
        const changed = netstorm.getPlayers(); changed[0].stormPower = 0;
        netstorm.log('info', JSON.stringify({ originalPower: netstorm.getPlayers()[0].stormPower, random: netstorm.randomInt(100) }));
        netstorm.commands.click(200, 300); netstorm.commands.pressKey('ArrowLeft'); netstorm.commands.selectPriest(); netstorm.commands.nextUnit(true); netstorm.commands.produceBridge(2); netstorm.commands.repeatProduction(); netstorm.commands.rotatePiece();
    });
    // 다음 입력 단계가 수용한 명령 번호와 요청 사건 번호를 보존한다.
    netstorm.on('commandResult', (event) => netstorm.log('info', JSON.stringify(event.results)));
    // 호스트 시간과 독립한 사건 시계와 모드 RNG를 기록한다.
    netstorm.on('tick', (event) => netstorm.log('info', JSON.stringify({ gameSeconds: event.gameSeconds, random: netstorm.randomInt(100) })));
    // 종료 전에 읽을 수 있는 마지막 상태를 기록한다.
    netstorm.on('sessionEnd', (event) => netstorm.log('info', JSON.stringify({ reason: event.reason, state: netstorm.getState() })));
}
